lfs_size_t lfs_alignup(lfs_size_t a, lfs_size_t alignment) {
    if (alignment == 0) {
        return 0;
    }
    return (a + alignment - 1) & ~(alignment - 1);
}

// Test cases
int main() {
    // Test 1: Align 5 to 4
    lfs_size_t result1 = lfs_alignup(5, 4); // Expected: 8

    // Test 2: Align 8 to 4
    lfs_size_t result2 = lfs_alignup(8, 4); // Expected: 8

    // Test 3: Align 0 to 4
    lfs_size_t result3 = lfs_alignup(0, 4); // Expected: 0

    // Test 4: Align 1 to 2
    lfs_size_t result4 = lfs_alignup(1, 2); // Expected: 2

    // Test 5: Align 15 to 8
    lfs_size_t result5 = lfs_alignup(15, 8); // Expected: 16

    // Test 6: Align to 0 (edge case)
    lfs_size_t result6 = lfs_alignup(10, 0); // Expected: 0

    return 0;
}

lfs_size_t lfs_alignup(lfs_size_t a, lfs_size_t alignment) {
    if (alignment == 0 || (alignment & (alignment - 1)) != 0) {
        return 0; // Invalid alignment
    }
    return (a + alignment - 1) & ~(alignment - 1);
}

// Test cases
int main() {
    // Test 1: Align 5 to 4 (valid)
    lfs_size_t result1 = lfs_alignup(5, 4); // Expected: 8

    // Test 2: Align 8 to 4 (valid)
    lfs_size_t result2 = lfs_alignup(8, 4); // Expected: 8

    // Test 3: Align 0 to 4 (valid)
    lfs_size_t result3 = lfs_alignup(0, 4); // Expected: 0

    // Test 4: Align 1 to 2 (valid)
    lfs_size_t result4 = lfs_alignup(1, 2); // Expected: 2

    // Test 5: Align 15 to 8 (valid)
    lfs_size_t result5 = lfs_alignup(15, 8); // Expected: 16

    // Test 6: Align to 0 (invalid)
    lfs_size_t result6 = lfs_alignup(10, 0); // Expected: 0

    // Test 7: Align to 3 (invalid, not power of 2)
    lfs_size_t result7 = lfs_alignup(10, 3); // Expected: 0

    return 0;
}

